def _missing(m):
    items = [ZH.get(x.strip(), x.strip()) for x in m.group(2).replace("&#39;", "'").split(", ")]
    return ("发布还缺少：" if m.group(1).startswith("Pour") else "还缺少：") + "、".join(items) + "。"


PATTERNS.insert(0, (r"^(Pour publier, il manque|Il manque) : (.+)\.$", _missing))

